import { z } from 'zod'
import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'
import { appendSessionEvent } from '../debug-graph/session'
import {
  loadMechanicsKernel,
  resolveMechanicsRepoRoot,
  type LoadMechanicsKernelOptions,
} from '../kernel'
import { validateMechanicsKernel } from '../kernel/validate'
import { compilePlannerPipeline } from '../planner-engine'
import { loadSaveGraphDegraded } from '../save-graph'
import { runTowerVm } from './vm'

const nodeRequire = createRequire(__filename)

export const SandboxModeSchema = z.enum([
  'check',
  'kernel',
  'save-graph',
  'planner',
  'decode',
  'vm',
])
export type SandboxMode = z.infer<typeof SandboxModeSchema>

export const SandboxRunRequestSchema = z.object({
  mode: SandboxModeSchema.default('check'),
  savePath: z.string().optional(),
  family: z.string().optional(),
})
export type SandboxRunRequest = z.infer<typeof SandboxRunRequestSchema>

export const SandboxRunResultSchema = z.object({
  ok: z.boolean(),
  mode: SandboxModeSchema,
  traces: z.array(z.object({
    step: z.string(),
    ok: z.boolean(),
    detail: z.unknown().optional(),
  })),
  remainingHumanPatches: z.number().int().nonnegative().optional(),
  errors: z.array(z.string()).default([]),
})
export type SandboxRunResult = z.infer<typeof SandboxRunResultSchema>

export interface SandboxOptions extends LoadMechanicsKernelOptions {
  request?: SandboxRunRequest
}

function tryDecodeSave(savePath: string, repoRoot: string): unknown {
  const abs = path.isAbsolute(savePath) ? savePath : path.join(repoRoot, savePath)
  if (!fs.existsSync(abs)) {
    throw new Error(`save path not found: ${abs}`)
  }
  if (/\.json$/i.test(abs)) {
    const json = JSON.parse(fs.readFileSync(abs, 'utf8'))
    return {
      kind: 'json-fixture',
      path: abs,
      topLevelKeys: Object.keys(json).filter(k => !k.startsWith('_')).slice(0, 40),
      keyCount: Object.keys(json).length,
    }
  }
  // Prefer built dist when present
  let decode: ((input: Uint8Array | Buffer) => { parsedRoot: Record<string, unknown>; wasGzip: boolean }) | null = null
  try {
    const nodeMod = nodeRequire(path.join(repoRoot, 'packages/sdk/dist/node/index.js'))
    decode = nodeMod.decodePlayerInfoSaveBytes
  } catch {
    decode = null
  }
  if (!decode) {
    return {
      kind: 'dat-bytes',
      path: abs,
      byteLength: fs.statSync(abs).size,
      skippedDecode: true,
      reason: 'thetowersdk/node build not found — run pnpm build in packages/sdk, or pass a .json fixture',
    }
  }
  const bytes = fs.readFileSync(abs)
  const result = decode(bytes)
  return {
    kind: 'dat-decoded',
    path: abs,
    wasGzip: result.wasGzip,
    topLevelKeys: Object.keys(result.parsedRoot).slice(0, 40),
    keyCount: Object.keys(result.parsedRoot).length,
  }
}

/**
 * Runtime sandbox — instrumented substrate + optional save decode / planner compile.
 * Never invents formulas.
 */
export function runMechanicsSandbox(opts: SandboxOptions = {}): SandboxRunResult {
  const request = SandboxRunRequestSchema.parse(opts.request ?? { mode: 'check' })
  const repoRoot = resolveMechanicsRepoRoot(opts.repoRoot)
  const traces: SandboxRunResult['traces'] = []
  const errors: string[] = []
  let remainingHuman: number | undefined

  const step = (name: string, fn: () => unknown) => {
    try {
      const detail = fn()
      traces.push({ step: name, ok: true, detail })
      try {
        appendSessionEvent({
          id: `sandbox.${name}.${Date.now()}`,
          kind: 'trace',
          at: new Date().toISOString(),
          exportName: `sandbox:${name}`,
          argsPreview: request.mode,
          durationMs: 0,
          mechanicNodeIds: [],
        }, repoRoot)
      } catch {
        // optional
      }
      return detail
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      errors.push(`${name}: ${message}`)
      traces.push({ step: name, ok: false, detail: { error: message } })
      return null
    }
  }

  if (request.mode === 'kernel' || request.mode === 'check') {
    step('kernel.load', () => {
      const ctx = loadMechanicsKernel({ ...opts, repoRoot }).context
      return { ok: ctx.ok, trustOk: ctx.trustOk }
    })
    step('kernel.validate', () => {
      const v = validateMechanicsKernel({ ...opts, repoRoot })
      if (!v.ok) errors.push(...v.errors.slice(0, 20))
      return { ok: v.ok, errorCount: v.errors.length }
    })
  }


  if (request.mode === 'save-graph' || request.mode === 'check') {
    step('save-graph.load', () => {
      const s = loadSaveGraphDegraded()
      if (s.errors.length) errors.push(...s.errors)
      return {
        nodeCount: Object.keys(s.graph.nodes).length,
        edgeCount: s.graph.edges.length,
        verifiedFields: Object.values(s.graph.nodes).filter(n => n.type === 'save.field' && n.status === 'verified').length,
        errors: s.errors,
      }
    })
  }

  if (request.mode === 'planner' || request.mode === 'check') {
    step('planner.compile', () => {
      const family = request.family ?? 'eEcon'
      const pipe = compilePlannerPipeline(family)
      return {
        family: pipe.family,
        codegen: pipe.codegen,
        steps: pipe.steps.map(s => ({ id: s.id, status: s.status })),
      }
    })
  }

  if (request.mode === 'decode' || request.savePath) {
    const savePath = request.savePath
      ?? 'packages/sdk/fixtures/save/perk-preferences.sample.json'
    step('save.decode', () => tryDecodeSave(savePath, repoRoot))
  }

  if (request.mode === 'vm') {
    step('vm.run', () =>
      runTowerVm({
        repoRoot,
        request: {
          family: request.family,
          savePath: request.savePath,
        },
      }),
    )
  }

  return SandboxRunResultSchema.parse({
    ok: errors.length === 0,
    mode: request.mode,
    traces,
    remainingHumanPatches: remainingHuman,
    errors,
  })
}

export { runTowerVm, type TowerVmRequest, type TowerVmResult } from './vm'
